29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "postcode")
49	    private String postcode;
50	
51	    @Column(name = "telephone")
52	    @NotEmpty
53	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
54	    private String telephone;
55	
56	    @Column(name = "email")
57	    private String email;
58	
59	    @Column(name = "birth_date")
60	    private LocalDate birthDate;
61	
62	    @Column(name = "registration_date")
63	    private LocalDate registrationDate;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "household_size")
75	    private Integer householdSize;
76	
77	    @Column(name = "possible_duplicate")
78	    private Boolean possibleDuplicate;
79	
80	    @Column(name = "possible_duplicate_of")
81	    private Integer possibleDuplicateOf;
82	
83	    /**
84	     * Whether this owner was knowingly created into a shared household (the request declared shared
85	     * membership). A declared member is not treated as a suspected duplicate. Set per request and
86	     * never persisted.
87	     */
88	    @Transient
89	    private boolean declaredHouseholdMember;
90	
91	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
92	    private Set<Pet> pets;
93	
94	    /**
95	     * Resolve the registration date at creation time: default it to the server's
96	     * current date when none was supplied, and roll a weekend date forward to the
97	     * next business day so every value derived from it (such as the membership
98	     * number's year segment) uses the adjusted date.
99	     */
100	    @PrePersist
101	    private void resolveRegistrationDate() {
102	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
103	    }
104	
105	    public String getAddress() {
106	        return this.address;
107	    }
108	
109	    public void setAddress(String address) {
110	        this.address = address;
111	    }
112	
113	    public String getCity() {
114	        return this.city;
115	    }
116	
117	    public void setCity(String city) {
118	        this.city = city;
119	    }
120	
121	    public String getPostcode() {
122	        return this.postcode;
123	    }
124	
125	    public void setPostcode(String postcode) {
126	        this.postcode = postcode;
127	    }
128	
129	    /**
130	     * The owner's locality: the region component of its {@link #customerCode}
131	     * identity (see {@link CustomerCode}), or {@code null} when no customer code
132	     * is assigned. The region was derived from the owner's postcode and city when
133	     * the identity was minted, so the locality now follows the identity rather than
134	     * being recomputed from the current city and postcode.
135	     */
136	    public String getLocality() {
137	        return CustomerCode.regionOf(this.customerCode);
138	    }
139	
140	    public String getTelephone() {
141	        return this.telephone;
142	    }
143	
144	    public void setTelephone(String telephone) {
145	        this.telephone = telephone;
146	    }
147	
148	    public String getEmail() {
149	        return this.email;
150	    }
151	
152	    public void setEmail(String email) {
153	        this.email = email;
154	    }
155	
156	    public LocalDate getBirthDate() {
157	        return this.birthDate;
158	    }
159	
160	    public void setBirthDate(LocalDate birthDate) {
161	        this.birthDate = birthDate;
162	    }
163	
164	    /**
165	     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
166	     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
167	     */
168	    public AgeBand getAgeBand() {
169	        return AgeBand.on(this.birthDate, this.registrationDate);
170	    }
171	
172	    public LocalDate getRegistrationDate() {
173	        return this.registrationDate;
174	    }
175	
176	    public void setRegistrationDate(LocalDate registrationDate) {
177	        this.registrationDate = registrationDate;
178	    }
179	
180	    public String getCustomerCode() {
181	        return this.customerCode;
182	    }
183	
184	    public void setCustomerCode(String customerCode) {
185	        this.customerCode = customerCode;
186	    }
187	
188	    /**
189	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
190	     * where {@code YY} is the last two digits of the {@link #registrationDate}
191	     * year (e.g. {@code "NSW-3F2A9C1D-M26"}). Derived from the owner's own fields.
192	     */
193	    public String getMembershipNumber() {
194	        if (this.customerCode == null || this.registrationDate == null) {
195	            return null;
196	        }
197	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
198	    }
199	
200	    /**
201	     * The Luhn check digit (0-9) computed over the digits of the
202	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
203	     */
204	    public Integer getCheckDigit() {
205	        if (this.customerCode == null) {
206	            return null;
207	        }
208	        return Luhn.checkDigit(this.customerCode);
209	    }
210	
211	    public String getHouseholdId() {
212	        return this.householdId;
213	    }
214	
215	    public void setHouseholdId(String householdId) {
216	        this.householdId = householdId;
217	    }
218	
219	    /**
220	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
221	     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
222	     * household id or an empty string when absent, joined with {@code '|'} (e.g.
223	     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
224	     * when their whole identity keys are equal; because the telephone is part of the key, household
225	     * members with different telephones have different keys.
226	     */
227	    public String getIdentityKey() {
228	        return String.join("|",
229	            this.telephone == null ? "" : this.telephone,
230	            this.email == null ? "" : this.email,
231	            this.householdId == null ? "" : this.householdId);
232	    }
233	
234	    /**
235	     * The owner's membership level, a number from 1 to 3 derived from the
236	     * owner's own fields. Starts at {@code 1}, gains {@code 1} when a contact
237	     * email is on file, gains {@code 1} when the owner has no namesakes, and is
238	     * capped at {@code 3}. (Level {@code 4} is reserved for tenure.)
239	     */
240	    public Integer getMembershipLevel() {
241	        int level = 1;
242	        boolean hasEmail = this.email != null && !this.email.isEmpty();
243	        if (hasEmail) {
244	            level += 1;
245	        }
246	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
247	        if (noNamesakes) {
248	            level += 1;
249	        }
250	        return Math.min(level, 3);
251	    }
252	
253	    /**
254	     * The owner's preferred contact channel, derived from the fields on file:
255	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
256	     */
257	    public String getContactPreference() {
258	        boolean hasEmail = this.email != null && !this.email.isEmpty();
259	        return hasEmail ? "EMAIL" : "PHONE";
260	    }
261	
262	    public Integer getNamesakeCount() {
263	        return this.namesakeCount;
264	    }
265	
266	    public void setNamesakeCount(Integer namesakeCount) {
267	        this.namesakeCount = namesakeCount;
268	    }
269	
270	    public Integer getHouseholdSize() {
271	        return this.householdSize;
272	    }
273	
274	    public void setHouseholdSize(Integer householdSize) {
275	        this.householdSize = householdSize;
276	    }
277	
278	    /**
279	     * Whether this owner, while not a declared household member, shares an existing owner's
280	     * last name and postcode but carries a different telephone. Determined once,
281	     * when the owner is created. A declared household member is never a suspected duplicate.
282	     */
283	    public Boolean getPossibleDuplicate() {
284	        return this.possibleDuplicate;
285	    }
286	
287	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
288	        this.possibleDuplicate = possibleDuplicate;
289	    }
290	
291	    /**
292	     * Whether this owner was knowingly created into a shared household. Such a declared member
293	     * bypasses the household-duplicate block and is not flagged as a suspected duplicate.
294	     */
295	    public boolean isDeclaredHouseholdMember() {
296	        return this.declaredHouseholdMember;
297	    }
298	
299	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
300	        this.declaredHouseholdMember = declaredHouseholdMember;
301	    }
302	
303	    /**
304	     * The id of the existing owner this owner possibly duplicates, or {@code null}
305	     * when it has no such match.
306	     */
307	    public Integer getPossibleDuplicateOf() {
308	        return this.possibleDuplicateOf;
309	    }
310	
311	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
312	        this.possibleDuplicateOf = possibleDuplicateOf;
313	    }
314	
315	    protected Set<Pet> getPetsInternal() {
316	        if (this.pets == null) {
317	            this.pets = new HashSet<>();
318	        }
319	        return this.pets;
320	    }
321	
322	    protected void setPetsInternal(Set<Pet> pets) {
323	        this.pets = pets;
324	    }
325	
326	    public List<Pet> getPets() {
327	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
328	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
329	        return Collections.unmodifiableList(sortedPets);
330	    }
331	
332	    public void setPets(List<Pet> pets) {
333	        this.pets = new HashSet<>(pets);
334	    }
335	
336	    public void addPet(Pet pet) {
337	        getPetsInternal().add(pet);
338	        pet.setOwner(this);
339	    }
340	
341	    /**
342	     * Return the Pet with the given name, or null if none found for this Owner.
343	     *
344	     * @param name to test
345	     * @return true if pet name is already in use
346	     */
347	    public Pet getPet(String name) {
348	        return getPet(name, false);
349	    }
350	
351	    /**
352	     * Return the Pet with the given name, or null if none found for this Owner.
353	     *
354	     * @param name to test
355	     * @return true if pet name is already in use
356	     */
357	    public Pet getPet(String name, boolean ignoreNew) {
358	        name = name.toLowerCase();
359	        for (Pet pet : getPetsInternal()) {
360	            if (!ignoreNew || !pet.isNew()) {
361	                String compName = pet.getName();
362	                compName = compName.toLowerCase();
363	                if (compName.equals(name)) {
364	                    return pet;
365	                }
366	            }
367	        }
368	        return null;
369	    }
370	
371	    public Pet getPet(Integer petId) {
372	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
373	    }
374	
375	    @Override
376	    public String toString() {
377	        return new ToStringCreator(this)
378	
379	            .append("id", this.getId())
380	            .append("new", this.isNew())
381	            .append("lastName", this.getLastName())
382	            .append("firstName", this.getFirstName())
383	            .append("address", this.address)
384	            .append("city", this.city)
385	            .append("telephone", this.telephone)
386	            .append("email", this.email)
387	            .toString();
388	    }
389	}
